def _unique_slug(model, value, max_length):
    base = (slugify(str(value)) or 'item')[:max_length]
    candidate = base
    index = 2
    while model.objects.filter(slug=candidate).exists():
        suffix = f'-{index}'
        candidate = f'{base[:max_length-len(suffix)]}{suffix}'
        index += 1
    return candidate


def populate_catalog_dictionaries(apps, schema_editor):
    Product = apps.get_model('shop', 'Product')
    CatalogBrand = apps.get_model('shop', 'CatalogBrand')
    CatalogColor = apps.get_model('shop', 'CatalogColor')
